import json
from pathlib import Path

from calc import add, mul

CASES = Path(__file__).resolve().parent.parent / "data" / "cases.json"


def _cases():
    return json.loads(CASES.read_text())


def test_add():
    assert add(2, 3) == _cases()["add_2_3"]


def test_add_negative():
    assert add(-1, -1) == _cases()["add_neg"]


def test_mul():
    assert mul(2, 3) == _cases()["mul_2_3"]

